save("0215","تعليمات تدريب طلبة الطب من الجامعات المختلفة غير جامعة العلوم والتكنولوجيا الأردنية (برنامج المساق الاختياري)",[
("procedure",[1],"البند 1 و2","يُشترط في الشخص الراغب بالتدريب أن يكون طالباً في كلية الطب البشري في برنامج البكالوريوس في الطب والجراحة، ويتقدم بطلب خاص إلى مكتب التدريب السريري في كلية الطب بالجامعة مرفقاً به: موافقة خطية من عميد كلية الطب التي يدرس فيها الطالب، ونموذج التقييم من الجهة المسؤولة عن المتقدم، وتحديد الفترة الزمنية التي ينوي قضاءها في التدريب السريري.",
 "ما شروط ووثائق طلب التدريب السريري لطلبة الطب من جامعات أخرى؟","كيف يتقدم طالب طب من جامعة أخرى للتدريب السريري في الجامعة؟","شو بحتاج طالب طب من جامعة ثانية عشان يتدرب عندكم؟"),
("number",[1],"البند 5 و6","يُشترط أن يكون المتقدم مؤمناً صحياً بتأمين ساري المفعول في الأردن خلال فترة وجوده في المساق الاختياري، ويدفع بعد حصوله على الموافقة رسماً قدره ألف دينار أردني مقابل كل دورة تدريبية (4 أسابيع) توزع 50% إلى أمانات الجامعة و50% إلى أمانات كلية الطب البشري.",
 "كم رسم التدريب السريري لطالب الطب من جامعة أخرى؟","كم تبلغ مدة الدورة التدريبية التي يغطيها رسم الألف دينار؟","كم بدفع طالب الطب من جامعة ثانية عن الدورة التدريبية؟"),
],"a",verified="image")
save("0220","تعليمات امتحان الإكمال للطلبة الراسبين في مساقات التدريب السريري لطلاب دكتور صيدلة",[
("number",[1],"البند 1","يحق للطالب التقدم لامتحان إكمال في مساق واحد فقط من مساقات التدريب السريري (4 ساعات معتمدة) من مستوى (600) لتخصص دكتور صيدلة طيلة مدة الدراسة. ويشترط أن يكون الرسوب بعلامة لا تقل عن 40% والحصول على مجموع أعمال فصلية لا يقل عن (50%) من مجموع علامات الأعمال الفصلية المخصصة لها، وألا يكون الطالب محروماً بسبب عقوبة تأديبية.",
 "من يحق له التقدم لامتحان الإكمال في مساقات التدريب السريري لدكتور صيدلة؟","كم مرة يحق للطالب التقدم لامتحان الإكمال في التدريب السريري؟","شو شروط امتحان الإكمال بمساقات التدريب السريري لطلاب دكتور صيدلة؟"),
("number",[1],"البند 3","يُعقد امتحان الإكمال في موعد أقصاه نهاية الأسبوع الثالث من بدء التدريس للطلبة في الفصل الدراسي اللاحق لفصل الرسوب، ويفقد الطالب حقه إذا لم يتقدم بطلبه خلال الفترة المعلنة أو أجّل الدراسة للفصل اللاحق.",
 "متى يُعقد امتحان الإكمال لمساقات التدريب السريري لدكتور صيدلة؟","ماذا يحدث إذا لم أتقدم بطلب الإكمال خلال الفترة المعلنة؟","متى بصير امتحان الإكمال للتدريب السريري؟"),
("number",[1],"البند 5 و6","الحد الأدنى لعلامة النجاح في امتحان الإكمال هو (50%)، ويرصد الرمز المقابل لعلامة الامتحان لكل علامة أقل من (60%)، وتثبت علامة (60%) برمز (ج-) كعلامة نهائية مستحقة لكل علامة امتحان تتراوح بين (60-100). وتبقى علامة الطالب الراسب في امتحان الإكمال كما كانت عليه في سجله الأكاديمي قبل التقدم للامتحان، وعليه إعادة دراسة مساق التدريب السريري.",
 "ما أدنى علامة نجاح في امتحان الإكمال لدكتور صيدلة وماذا تُثبت للناجح؟","ماذا يحدث إذا رسب الطالب في امتحان الإكمال؟","كم علامة النجاح بامتحان الإكمال وشو بتصير علامتي؟"),
],"a",verified="image")
save("0223","اللائحة التنظيمية للتدريب العملي لطلبة كليات الهندسة والصيدلة والعلوم والآداب",[
("rule",[1],"أهداف التدريب","من أهداف التدريب العملي: الإلمام بالقوانين والتعليمات المعمول بها في الأردن والمتعلقة بممارسة المهنة وأخلاقياتها، وتعميق وتعزيز المفاهيم العلمية الأساسية التي درسها الطالب، وتوطيد العلاقة بين كليات الجامعة والمؤسسات ذات العلاقة، ومساعدة الطلبة في إيجاد فرص عمل بعد التخرج، واكتساب المهارات العلمية والميدانية اللازمة لممارسة المهنة.",
 "ما أهداف التدريب العملي لطلبة الهندسة والصيدلة والعلوم والآداب؟","ما الغاية من التدريب العملي حسب اللائحة التنظيمية؟","شو الهدف من التدريب العملي؟"),
("number",[1],"أسس التدريب (و)","على الطالب أن يتفرغ فراغاً كاملاً خلال فترة التدريب بحيث لا يجوز له أن يجمع بين التدريب ودراسة أية مساقات أخرى، ويمكن الجمع بين التدريب ودراسة (3) ساعات معتمدة في الفصلين الأول والثاني.",
 "هل يجوز للطالب دراسة مساقات أخرى أثناء التدريب العملي؟","كم ساعة معتمدة يمكن الجمع بينها وبين التدريب العملي؟","بقدر أدرس مواد ثانية وأنا بتدرب؟"),
("number",[1],"أسس التدريب (ج و د)","يكون هناك دفتر دوام (Log Book) لكل طالب يتم توقيعه يومياً من مسؤول التدريب في الجهة التي يتدرب بها الطالب ويكون مبيناً فيه شرح للأعمال التي تدرب عليها. ويحسب لكل مشرف تدريب عبء تدريسي بواقع (3) ساعات معتمدة في الفصل الصيفي فقط وذلك لكل عدد من الطلبة يتراوح بين (30-40) طالباً.",
 "ما دفتر الدوام (Log Book) في التدريب العملي ومن يوقعه؟","كم ساعة معتمدة يُحسب عبئاً تدريسياً للمشرف في التدريب العملي؟","شو الـ Log Book بالتدريب العملي؟"),
("rule",[1],"أسس التدريب (ز)","من مهام مشرف التدريب: المساعدة في إيجاد أماكن تدريب لجميع الطلبة، والقيام بالاتصالات والزيارات الميدانية لأماكن التدريب قبل البدء للتأكد من صلاحيتها، وإعداد برنامج زمني لكل طالب، وإعداد نموذج تقييم، ومناقشة الأمور المتعلقة بالتدريب مع المشرف الميداني، والقيام بزيارات ميدانية للطلبة المتدربين مرة واحدة كل ثلاثة أسابيع على الأقل، وعقد اجتماع مع الطلبة مرة واحدة كل أسبوعين.",
 "ما مهام مشرف التدريب العملي؟","كم مرة يزور المشرف الطلبة المتدربين ميدانياً؟","كل قديش بزور المشرف الطلاب بمكان التدريب؟"),
],"a",verified="image")
save("0242","أسس القبول الجامعي لدرجة البكالوريوس لأبناء المدرسين السريريين العاملين في وزارة الصحة (البرنامج الموازي)",[
("number",[1],"البند 5","يمكن لأبناء المدرسين السريريين المنافسة على المقاعد إذا تحققت جميع الشروط: الانتظام في تعليم وتدريب الطلبة لعامين دراسيين متصلين على الأقل، وأن يكون مكلفاً بالتدريس أو التدريب من عميد الكلية في فصل القبول، وأن يكون مكلفاً مقابل مكافأة شهرية من الجامعة بإثبات من الشؤون المالية، وأن تكون شهادة الثانوية العامة أردنية أو أجنبية وصادرة سنة تقديم الطلب.",
 "ما شروط منافسة أبناء المدرسين السريريين على مقاعد البرنامج الموازي؟","كم عاماً يجب أن ينتظم المدرس السريري في التدريس لينافس ابنه على المقعد؟","شو الشروط عشان ابن المدرس السريري يتنافس على مقعد؟"),
("number",[1],"البند 6 و7","يتنافس الطلبة أبناء المدرسين السريريين على مقعد جامعي واحد في كل تخصص من تخصصات الجامعة باستثناء الصيدلة، وعلى مقعدين في تخصص دكتور صيدلة على النظام الموازي (كامل الرسوم)، وتتم القبولات تنافسياً حسب معدلات الثانوية العامة.",
 "كم مقعداً لأبناء المدرسين السريريين في كل تخصص؟","كم مقعداً في دكتور صيدلة لأبناء المدرسين السريريين؟","كم مقعد إلهم بكل تخصص؟"),
("number",[1],"البند 8 و10","يحتفظ أبناء المدرسين بحق المنافسة إذا أكمل آباؤهم عشر سنوات على الأقل بتدريس الطلبة حتى لو لم يكونوا على رأس عملهم، وتقدم طلبات الالتحاق لهذه الفئة على الفصل الدراسي الأول من كل عام جامعي.",
 "متى يحتفظ ابن المدرس السريري بحق المنافسة رغم ترك الأب عمله؟","على أي فصل تقدم طلبات القبول لأبناء المدرسين السريريين؟","متى بقدموا ولاد المدرسين السريريين طلب القبول؟"),
],"a",verified="text")
